// Determine update type and build notifier command args.
// Supported:
//   callback_query with data 'mark_sent:<job_id>'
//   message text '/status <job_id>'
//   message text '/update <job_id> <statut>'
//   message text '/note <job_id> <texte libre>'
const body = $input.first().json.body || $input.first().json;
let chatId, callbackQueryId, commandArgs;

if (body.callback_query) {
  const cq = body.callback_query;
  chatId = String(cq.message.chat.id);
  callbackQueryId = cq.id;
  // data format: 'action:job_id'
  const colonIdx = cq.data.indexOf(':');
  const action = colonIdx >= 0 ? cq.data.slice(0, colonIdx) : cq.data;
  const jobId = colonIdx >= 0 ? cq.data.slice(colonIdx + 1) : '';
  commandArgs = `${action} ${jobId}`.trim();
} else if (body.message && body.message.text && body.message.text.startsWith('/')) {
  const msg = body.message;
  chatId = String(msg.chat.id);
  callbackQueryId = null;
  // Strip leading '/' — notifier expects 'status <id>', not '/status <id>'
  commandArgs = msg.text.trim().slice(1);
} else {
  // Non-command updates (stickers, etc.) — ignore silently
  return [];
}

return [{ json: { chatId, callbackQueryId, commandArgs } }];

const execOut = $input.first().json;
const parsed = $('Parse Telegram Update').first().json;
const chatId = parsed.chatId;
const callbackQueryId = parsed.callbackQueryId;
const stdout = (execOut.stdout || '').trim();
let message = '\u274c Erreur interne.';
try {
  const result = JSON.parse(stdout);
  message = result.message || message;
} catch (_) {
  // stdout was not valid JSON — keep default error message
}
return [{ json: { chatId, callbackQueryId, message } }];
